"""Build audit-to-code matrix and bilingual offline release guide. No network."""
from pathlib import Path
import json,html,base64
R=Path(__file__).resolve().parents[1]
rows=[
('A01','Editable drawing master','\u53ef\u7de8\u8f2f\u4f5c\u756b\u4e3b\u6a94','new','Native geometry, anchors, lineage, source hashes and bounded history, not only a PNG.','atelier.js: markAsset / begin / finish','Source history, fork, snapshot tests','Raster does not become native geometry automatically.'),
('A02','Rough, clean and correction','\u7c97\u7a3f\uff0f\u6e05\u7a3f\uff0f\u4fee\u6b63\u7a3f','new','Five authored planes with separate final/guide rendering and plane-local erasing.','atelier-ui.js; engine.js: drawingSVG','Plane isolation and legacy eraser regression','Unassigned legacy erasers preserve the original combined behavior.'),
('A03','Freehand input','\u624b\u7e6a\u8207\u58d3\u529b\u7b46\u8de1','new','Coalesced pointer samples, saved pressure, live weighted stabilization, endpoint taper and batch strokes.','atelier-ui.js: down / move / up','Real mouse gestures; stored sample bounds','Physical tablet and model-controlled pen not tested. Not a full textured raster brush engine.'),
('A04','View and coordinate control','\u756b\u5e03\u65cb\u8f49\u8207\u5ea7\u6a19\u5c0d\u4f4d','new','View-only zoom/pan/rotation; inverse mapping into asset or scene coordinates.','atelier-ui.js: viewMatrix / mapPoint','Rotated/zoomed pointer test','View transforms do not imply new camera-angle artwork.'),
('A05','Local drawing edits','\u7bc0\u9ede\u8207\u5c40\u90e8\u9078\u53d6','integrated-existing','Native node drag plus selection transforms, plane assignment and copy-on-write exposure.','pro.js; atelier.js: selection / drawing_fork','Node, shared source, outside exposure tests','Editable native subset; not automatic tracing.'),
('A06','Raster/vector coexistence','\u9ede\u9663\u53c3\u8003\u8207\u624b\u52d5\u63cf\u7dda','integrated-existing','Import raster reference, pin it, draw on a new native layer, preserve original.','atelier-ui.js: import / atNewDrawing','Reference pin; inherited raster import tests','No automatic semantic decomposition or background completion.'),
('A07','Model sheets and semantic parts','\u89d2\u8272\u8a2d\u5b9a\u8207\u90e8\u4ef6','new','Character notes, palette references, proportions, named parts, poses and contact anchors.','atelier.js: reference / character / part / anchor commands','Reference/part/anchor GUI and validation','Labels encode author intent, not machine-recognized anatomy.'),
('A08','Pose-first animation','\u95dc\u9375\u59ff\u52e2\u8207\u66dd\u5149','integrated-existing','Key/breakdown/inbetween markers share shot timing and existing exposure/pose tools.','atelier.js: pose_mark; engine.js / pro.js','Pose retime, trim and restart','Author must supply viable poses; no automatically inferred acting.'),
('A09','Editable clean-line inbetweens','\u5e36\u8272\u539f\u756b\u7684\u7dda\u7a3f\u88dc\u9593','new','Strip derived paint from compatible endpoints; make editable line cels and optional seeded color.','atelier.js: line_inbetween','Filled endpoint and topology rejection tests','Correspondence required; no invented limbs, turns, hidden surfaces or raster inpainting.'),
('A10','Fix line/paint audit defect','\u4fee\u5fa9\u6539\u7dda\u5f8c\u8272\u584a\u904e\u671f','corrected','Old and new editing paths invalidate region provenance when line geometry changes.','atelier.js: finish; engine.js: apply','Reproduction of v0.5 stale-fill bug','Stale derived fill is hidden; source runs are retained.'),
('A11','Safe color-region reconstruction','\u7a2e\u5b50\u8272\u57df\u8207\u6b67\u7fa9\u5be9\u6838','new','Native barriers, small gap closing, seed matching, split/merge/large-change review.','atelier-paint.js: components / rebuild / resolve','Split/merge/manual resolve and work budget tests','2,097,152 native pixels; 0..3px gap; legacy fills need seeds. Ambiguity is not auto-approved.'),
('A12','Named paint sources','\u8272\u7968\u8207\u5e73\u5857\u5206\u96e2','integrated-existing','Reuses named palette with geometry validity tracked separately from color changes.','engine.js: palette; atelier.js: lineData / stageInputs','Palette updates and stage invalidation','Color consistency is data-linked, not aesthetic judgment.'),
('A13','Authored shading','\u9670\u5f71\uff0f\u9ad8\u5149\uff0f\u5149\u6e90\u5099\u8a3b','new','Editable shadow/highlight planes tied to line, palette and authored light brief.','atelier.js: plane_review / planeFingerprint / light_set','Line/color/light invalidation tests','Light direction is reference metadata, not physical rendering or AI shading.'),
('A14','Shared deterministic preview','\u540c\u6838\u5fc3\u7dda\u7a3f\u3001\u5e73\u5857\u3001\u5408\u6210','new','Same renderer serves GUI and PNG MCP, asset/scene crop, onion and plane modes.','atelier-render.js; engine.js','Actual PNG decode, modes and coordinate map tests','Browser sRGB; exact patches still use established PNG compositor.'),
('A15','Related-change analysis','\u4fee\u6539\u9023\u5e36\u5f71\u97ff','new','Asset, parent, matte, driver, skin, camera, order, timing and patch dependencies; semantic relations.','atelier.js: impact','Protected order/patch/bone and contact tests','Conservative whole-shot bounds; relationships are not an automatic physics solver.'),
('A16','Protected editing scopes','\u76ee\u6a19\uff0f\u9023\u5e36\uff0f\u4fdd\u8b77\u7bc4\u570d','new','Preview/commit enforce target and allowed-related layers, protected layers and optional frame interval.','core.js: preview / commit; atelier.js: assertScope','Atomic and cross-shot scope tests','Structural guarantees are not the same as unchanged final pixels.'),
('A17','Pixel evidence','\u4fee\u6539\u524d\u5f8c\u50cf\u7d20\u5dee\u7570','new','Actual rendered difference image, changed counts inside/outside allowed box and channel delta.','atelier-render.js: render; preview-broker.cjs','Real MCP difference PNG and GUI compare','Measured output resolution only; unsampled pixels are not certified.'),
('A18','Use the right animation mechanism','\u63db\u756b\u3001\u8b8a\u5f62\u3001\u88dc\u756b\u8207\u4fee\u88dc','integrated-existing','Exposure, rig, mesh, corrective drivers and tracking retained alongside native redrawing.','engine.js; pro.js; tracking.js; atelier.js','306 previous core tests plus browser regression','No claim that warping or tracking replaces new expressive drawings.'),
('A19','Unified production workflow','\u88fd\u4f5c\u968e\u6bb5\u6574\u5408','new','Ten stages: lookdev, board, layout, animation, cleanup, paint, background, composite, sound, delivery.','atelier.js: STAGES / pipeline; atelier-ui.js','Stage GUI and upstream blocking','Stage status organizes work; not all commercial-suite depth is implemented.'),
('A20','Revision-aware approval','\u4e0a\u6e38\u6539\u7a3f\u8207\u4e0b\u6e38\u91cd\u5be9','new','Content fingerprints bind approval, detect stale upstream work and block invalid paint/delivery.','atelier.js: stageFingerprint / stageStatus / blockingForStage','Cascading stale approval and actual restart','Reviewer is a local label, not authenticated sign-off or automatic aesthetic approval.'),
('A21','Preserved lineage and recovery','\u7248\u672c\u8207\u539f\u7a3f\u4fdd\u7559','integrated-existing','Native parent links, retained runs, reversible shot-metadata cleanup, persistent proposals and checkpoints.','atelier.js; vault.js; lib/store.cjs','Undo, source preservation, disk restart','Use full backups; do not open Atelier-authored files in <=0.5.'),
('A22','Typed semantic MCP','\u5177\u578b\u53c3\u6578\u7684 MCP','new','24 strict command schemas, scoped proposals, provenance read and schema lookup.','tools/mcp.cjs; docs/ATELIER-SCHEMAS.json','Real subprocess tools/list and typed rejection','Older generic prod_* tools retained; no arbitrary code evaluation.'),
('A23','MCP that returns images','\u53ef\u56de\u50b3\u5716\u7247\u7684 MCP','new','Real PNG content with revision, source SHA-256, crop and coordinate transforms; error without worker.','lib/preview-broker.cjs; atelier-render.js; tools/mcp.cjs','Actual stdio image decoding and no-worker/stale tests','Requires active browser on same server. Local browser navigation was policy-blocked in this test environment; bridge caveat documented.'),
('A24','Human/agent handoff','\u4eba\u8207\u4ee3\u7406\u7684\u7de8\u8f2f\u4ea4\u63a5','new','Project-level timed lease, owner credential, atomic revisions, readable previews and explicit release.','lib/edit-lease.cjs; server.cjs; atelier-ui.js','Real second-client denial, human GUI handoff and expiry','No distributed/cloud collaboration. Actual Codex account not used.'),
('A25','Sound and delivery stay connected','\u8072\u97f3\u8207\u8f38\u51fa\u540c\u5c6c\u5c08\u6848','integrated-existing','Existing audio tracks, envelope, render cache and batch queue remain in shared Session and stage inputs.','audio.js; batch-queue.cjs; atelier.js: stageInputs','Inherited audio/queue and shared-server tests','Browser must stay open to render; FFmpeg optional and not bundled.'),
('A26','Measured comparison, not guessed benchmarks','\u5be6\u6e2c\u7d00\u9304\u800c\u975e\u5047\u8a2d\u6392\u540d','instrumented','Trial recorder exports declared route, source fingerprint, actions, duration and intervention events.','atelier-ui.js: reportEvent / run controls','Actual exported browser trial JSON','No measured Astra-vs-GUI winner, token cost or model identity claim.'),
]
items=[dict(zip(['id','conclusion','titleZh','status','implemented','source','verification','limits'],row)) for row in rows]
matrix={'version':'0.6.0-alpha','scope':'All conclusions of previous line/paint/workflow/MCP audit, not only the concluding example','items':items,'interpretation':'new/corrected are implemented here; integrated-existing retains and connects real prior functions; instrumented is measurement capability, not an unperformed model benchmark.'}
(R/'docs/AUDIT-IMPLEMENTATION-MATRIX.json').write_text(json.dumps(matrix,ensure_ascii=False,indent=2)+'\n')
# Retain historical guides without presenting their assertions as this release.
old=R/'Guide.zh-TW.html';archive=R/'docs/previous/Guide-v0.5.zh-TW.html'
