style='''body{margin:0;background:#f4f5f1;color:#192b34;font:17px/1.8 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:48px 32px}h1{font-size:42px;line-height:1.25}h2{margin-top:44px;color:#215b55}h3{margin-top:30px}p{max-width:940px}.badge{font-size:13px;background:#154f49;color:white;padding:6px 12px;border-radius:4px}table{width:100%;border-collapse:collapse;font-size:14px;line-height:1.65}th,td{padding:13px;text-align:left;border-bottom:1px solid #ccd8d2;vertical-align:top}th{background:#deebe4}tr:nth-child(even){background:#edf2ed}code,pre{font-family:ui-monospace,monospace}pre{background:#172c35;color:#e5f4ed;padding:22px;overflow:auto;border-radius:8px}a{color:#17675d}.note{background:#f2e9d4;padding:18px 24px;border-left:5px solid #98712a}.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.card{background:white;padding:22px;border:1px solid #d3ddd7;border-radius:8px}img{width:100%;height:auto}small{color:#536564}.tag{font-size:12px;display:block;color:#476760}@media(max-width:750px){main{padding:26px 14px}.cards{display:block}table{font-size:12px}td{padding:8px}}'''
