body+='<h2>02 / \u4e00\u689d\u53ef\u4ee5\u5be6\u969b\u64cd\u4f5c\u7684\u4fee\u7a3f\u6d41\u7a0b</h2>'
steps=[
('\u5efa\u7acb\u6216\u9078\u64c7\u756b\u7a3f','\u4f7f\u7528 Native study \u6216 Create clean-line layer\u3002\u9ede\u9663\u5716\u7247\u53ef\u4f5c\u53c3\u8003\uff0c\u4e0d\u6703\u81ea\u52d5\u8f49\u6210\u6709\u89e3\u5256\u610f\u7fa9\u7684\u9aa8\u67b6\u3002'),
('\u7e6a\u88fd\u7dda\u7a3f','\u5728 rough \u756b\u52d5\u4f5c\u5e95\u7a3f\uff0c\u5728 line \u756b\u6b63\u5f0f\u8f2a\u5ed3\uff0c\u5728 correction \u7559\u4fee\u6b63\u7b46\u8a18\u3002\u6b63\u5e38\u5408\u6210\u4e0d\u986f\u793a\u7c97\u7a3f\u8207\u4fee\u6b63\u7b46\u8a18\u3002'),
('\u4e0a\u8272\u8207\u6539\u7dda','\u5728 Paint \u9078\u8272\uff0c\u7528 seed \u9ede\u64ca\u5c01\u9589\u5340\u57df\u3002\u4f7f\u7528 node \u62d6\u52d5\u8f2a\u5ed3\u5f8c\uff0c\u53d7\u5f71\u97ff\u8272\u584a\u6703\u88ab\u6a19\u793a stale\uff1b\u6309 Rebuild seeded regions \u91cd\u5efa\u3002'),
('\u8655\u7406\u6b67\u7fa9','\u8272\u57df\u5206\u88c2\u6216\u5408\u4f75\u4e0d\u6703\u81ea\u52d5\u901a\u904e\u3002\u5206\u88c2\u5019\u9078\u9700\u8981\u6aa2\u8996\u5f8c\u63a5\u53d7\uff1b\u5408\u4f75\u885d\u7a81\u9700\u522a\u9664\u820a\u6307\u6d3e\u518d\u91cd\u65b0\u4e0b\u7a2e\u5b50\u3002'),
('\u4fdd\u8b77\u539f\u7a3f','\u55ae\u683c\u4fee\u6539\u9810\u8a2d\u5148 Fork current exposure\u3002\u78ba\u5be6\u8981\u6539\u5171\u7528\u7d20\u6750\u6642\uff0c\u624d\u52fe\u9078 Allow shared source edit\u3002\u6240\u6709\u4fee\u6539\u547d\u4ee4\u4e0d\u6703\u81ea\u52d5\u89e3\u9396\u4fdd\u8b77\u90e8\u4ef6\u3002'),
('\u5be9\u6838\u8207\u8f38\u51fa','\u7528 Pipeline \u6aa2\u67e5\u76f8\u4f9d\u95dc\u4fc2\u8207\u6838\u51c6\u72c0\u614b\uff0c\u518d\u7528 Compare \u6aa2\u67e5\u4fee\u6539\u524d\u5f8c\u5dee\u7570\u3002\u4e0a\u6e38\u66f4\u6539\u6703\u4f7f\u76f8\u95dc\u6838\u51c6\u9700\u8981\u91cd\u5be9\uff0c\u4e0d\u662f\u6c38\u4e45\u6709\u6548\u3002')]
body+='<div class="cards">'+''.join('<div class="card"><h3>'+h+'</h3><p>'+t+'</p></div>' for h,t in steps)+'</div>'
body+='<h2>03 / 26 \u9805\u5168\u90e8\u6aa2\u8996\u7d50\u8ad6\u5c0d\u7167</h2>'+para('\u4ee5\u4e0b\u4fdd\u7559\u82f1\u6587\u7a0b\u5f0f\u540d\u7a31\u8207\u9650\u5236\uff0c\u4fbf\u65bc\u4ee3\u7406\u8207\u958b\u767c\u8005\u6838\u5c0d\u3002\u53e6\u9644\u53ef\u6a5f\u5668\u8b80\u53d6\u7684 <code>docs/AUDIT-IMPLEMENTATION-MATRIX.json</code>\u3002')
